-- 003_videos.sql — acervo "Linguagem Simples na Mídia" (vídeos do YouTube).
-- Leitura pública (inclusive anônima); escrita apenas por service_role (esta carga)
-- ou, futuramente, por área administrativa autenticada (@tce.sp.gov.br) — ver SPEC.

create table if not exists videos (
  id           uuid primary key default gen_random_uuid(),
  n            int,
  categoria    text,
  titulo       text not null,
  canal        text,
  duracao_txt  text,
  duracao_seg  int default 0,
  short        boolean default false,
  publicado    date,
  descricao    text,
  youtube_id   text not null unique,
  url          text not null,
  criado_em    timestamptz default now()
);

create index if not exists videos_publicado_idx on videos (publicado desc);
create index if not exists videos_categoria_idx on videos (categoria);

alter table videos enable row level security;
drop policy if exists videos_sel on videos;
create policy videos_sel on videos for select using (true);

on conflict (youtube_id) do nothing;
